// ---- Place the two strategy sections in their teaching positions ----
(function placeStrategySections() {
  const weDoSec = document.getElementById('weDoGrid').closest('section');
  const checkSec = document.getElementById('checkpointGrid').closest('section');
  const ea = document.getElementById('errAnalysisSection');
  const hinge = document.getElementById('hingeSection');
  weDoSec.parentNode.insertBefore(ea, weDoSec.nextSibling);   // Error Analysis closes the We Do
  checkSec.parentNode.insertBefore(hinge, checkSec);          // Hinge question opens the You Do
  // Topic-specific wording for the frame's generic notes
  const tip = weDoSec.querySelector('.parts-instructions');
  if (tip) tip.innerHTML = '💡 <strong>Why we do it this way:</strong> write the absolute error first, then divide by the <strong>exact</strong> value, then multiply by 100%. Dividing by the exact value compares the error with the true size of the thing being measured.';
  const matchDesc = document.getElementById('matchArea').closest('section').querySelector('.sec-desc');
  if (matchDesc) matchDesc.textContent = 'Click a term, then click its partner. There are five matching pairs in the grid below.';
  const d1 = document.querySelector('#tier1-body .sec-desc');
  if (d1) d1.innerHTML = 'Type numbers only: no units and no % sign. Give exact decimals, e.g. <code>0.05</code> or <code>12.5</code>.';
  const d2 = document.querySelector('#tier2-body .sec-desc');
  if (d2) d2.innerHTML = 'Contexts, reverse problems and signed errors. Read carefully which value is exact. Type numbers only, or the word asked for.';
  const d3 = document.querySelector('#tier3-body .sec-desc');
  if (d3) d3.innerHTML = 'Multi-step problems with money and tolerances. Type numbers only: no units, $ or % sign needed.';
})();

// ---- Error Analysis kit ----
let errFound = false;
function pickErrLine(el) {
  if (errFound || el.classList.contains('dimmed')) return;
  if (el.dataset.isError === 'true') {
    el.classList.add('flagged-correct');
    errFound = true;
    document.querySelectorAll('.err-line').forEach(o => { if (o !== el) o.classList.add('dimmed'); });
    document.getElementById('errFeedback').classList.add('visible');
  } else {
    el.classList.add('flagged-wrong');
    setTimeout(() => el.classList.remove('flagged-wrong'), 600);
  }
}
function checkErrCorrection() {
  const input = document.getElementById('errCorrection');
  const expected = document.querySelector('.err-line[data-is-error="true"]').dataset.correctLine;
  const msg = document.getElementById('errStatusMsg');
  input.classList.remove('correct', 'incorrect');
  if (answerMatches(input.value, expected)) {
    input.classList.add('correct');
    msg.textContent = '✓ Correct. Line 3 should now read 0.2 × 100% = 20%, not 25%.';
  } else {
    input.classList.add('incorrect');
    msg.textContent = '✗ Not quite. Divide the absolute error (8) by the exact value (the actual maximum).';
  }
}

// ---- Hinge Question kit ----
function pickHingeOption(btn) {
  if (btn.classList.contains('dimmed')) return;
  const isCorrect = btn.dataset.correct === 'true';
  btn.classList.add('selected', isCorrect ? 'correct' : 'incorrect');
  document.querySelectorAll('.hinge-opt').forEach(o => { if (o !== btn) o.classList.add('dimmed'); });
  document.querySelectorAll('.hinge-feedback').forEach(f => f.classList.remove('visible'));
  const fbId = btn.dataset.feedbackId;
  if (fbId) document.getElementById(fbId).classList.add('visible');
}
function resetHinge() {
  document.querySelectorAll('.hinge-opt').forEach(o => o.classList.remove('selected', 'correct', 'incorrect', 'dimmed'));
  document.querySelectorAll('.hinge-feedback').forEach(f => f.classList.remove('visible'));
}
